  F2: { valuePct: 17.35, costPct: 28.13, riskPct: 29.63, priority: 0.404 },
  F3: { valuePct: 19.39, costPct: 25, riskPct: 25.93, priority: 0.511 },
  F4: { valuePct: 7.14, costPct: 9.38, riskPct: 7.41, priority: 0.546 },
  F5: { valuePct: 19.39, costPct: 18.75, riskPct: 22.22, priority: 0.649 },
  F6: { valuePct: 14.29, costPct: 6.25, riskPct: 3.7, priority: 1.763 },
};
const RANKING = ["F6","F1","F5","F4","F3","F2"];

// B. From what each stakeholder really said.
const MOSCOW = {
  F1: 'Must',
  F2: 'Won\'t',
  F3: 'Should',
  F4: 'Could',
  F5: 'Should',
  F6: 'Must',
};

// D. Add a member · book for a member (BR-03 per person) · what reception sees.
const FAMILY_STORIES = [
  {
    "story": "As a patient, I want to add my child as a family member to my account so that I can book visits for them.",
    "criteria": [
      "Given I am signed in, when I add a family member with name and date of birth, then the member appears in my family list.",
      "Given a family member is already in my list, when I add the same name and date of birth again, then the system refuses the duplicate."
    ]
  },
  {
    "story": "As a patient, I want to choose a family member when I book so that the appointment is for the right person.",
    "criteria": [
      "Given I have a family member, when I book a slot for that member, then the appointment shows the member as the patient.",
      "Given my child already holds 2 future appointments, when I book a third for the child, then the system refuses it although I hold fewer than 2 future appointments myself."
    ]
  },
  {
    "story": "As a receptionist, I want to see who an appointment is for and who booked it so that I check in the right person.",
    "criteria": [
      "Given an appointment booked by a parent for a child, when I open the daily schedule, then I see the child as patient and the parent as booker."
    ]
  }
];

